 "content": "def transform(grid):
    """Draw color-6 main diagonals across the grid and join diagonal color-1 pairs."""
    out = [row[:] for row in grid]
    h, w = len(grid), len(grid[0])
    background = next(value for row in grid for value in row if value not in (1, 6))
    original = [(r, c, grid[r][c]) for r in range(h) for c in range(w) if grid[r][c] in (1, 6)]

    # Color 6 marks a complete down-right diagonal, extended to both borders.
    for r, c, color in original:
        if color != 6:
            continue
        rr, cc = r, c
        while rr > 0 and cc > 0:
            rr -= 1
            cc -= 1
        while rr < h and cc < w:
            if out[rr][cc] == background:
                out[rr][cc] = 6
            rr += 1
            cc += 1

    # Join any color-1 markers sharing a diagonal, retaining all original markers.
    ones = [(r, c) for r, c, color in original if color == 1]
    for i, (r1, c1) in enumerate(ones):
        for r2, c2 in ones[i + 1:]:
            dr, dc = r2 - r1, c2 - c1
            if abs(dr) != abs(dc):
                continue
            step_r = 1 if dr > 0 else -1 if dr < 0 else 0
            step_c = 1 if dc > 0 else -1 if dc < 0 else 0
            rr, cc = r1, c1
            while True:
                if out[rr][cc] == background:
                    out[rr][cc] = 1
                if (rr, cc) == (r2, c2):
                    break
                rr += step_r
                cc += step_c
    return out


